// Сверка S3 ↔ локальная папка. На выходе — по одному item на файл, который надо скачать,
// либо один item { nothing: true } с планом/статистикой (dry_run или нет изменений).
const cfg = $('Конфиг').first().json;
const prefix = String(cfg.s3_prefix || '').replace(/^\/+/, '');
const localDir = String(cfg.local_dir || '/data/studio-engine/public').replace(/\/+$/, '');
const dryRun = cfg.dry_run === true || cfg.dry_run === 'true';

// локальные файлы: строки "./rel|size|mtime"
const stdout = String($('Локальные файлы').first().json.stdout || '');
const local = new Map();
for (const line of stdout.split('\n')) {
  const m = line.match(/^\.\/(.+)\|(\d+)\|(\d+)\s*$/);
  if (m) local.set(m[1], { size: Number(m[2]), mtime: Number(m[3]) });
}

const s3 = $('S3 · Список файлов').all().map(i => i.json).filter(o => o && o.Key);
const out = [];
let same = 0, missing = 0, changed = 0, skipped = 0;
for (const o of s3) {
  const key = String(o.Key);
  if (key.endsWith('/')) { skipped++; continue; }                 // «папки»
  if (prefix && !key.startsWith(prefix)) { skipped++; continue; }
  const rel = key.slice(prefix.length).replace(/^\/+/, '');
  if (!rel || rel.split('/').includes('..')) { skipped++; continue; }
  const size = Number(o.Size ?? o.ContentLength ?? -1);
  const s3Time = Math.floor(new Date(o.LastModified).getTime() / 1000);
  const loc = local.get(rel);
  let reason;
  if (!loc) { reason = 'новый'; missing++; }
  else if (size >= 0 && loc.size !== size) { reason = `размер ${loc.size}→${size}`; changed++; }
  else if (s3Time > loc.mtime) { reason = 'обновлён в S3'; changed++; }
  else { same++; continue; }
  const local_path = `${localDir}/${rel}`;
  const local_dir_parent = local_path.slice(0, local_path.lastIndexOf('/'));
  out.push({ Key: key, rel, size, reason, local_path, local_dir_parent });
}

const stats = { s3_total: s3.length, local_total: local.size, same, missing, changed, skipped,
  to_download: out.length, dry_run: dryRun, prefix, local_dir: localDir };

if (dryRun || out.length === 0) {
  return [{ json: { nothing: true, stats, plan: out.map(o => `${o.reason}: ${o.rel}`) } }];
}
return out.map(o => ({ json: { ...o, stats } }));

const first = $('Сравнение').first().json;
const stats = first.stats || {};
let written = 0;
try { written = $('Запись файла').all().length; } catch (e) { written = 0; }
const lines = [
  `S3 «${stats.prefix}» → ${stats.local_dir}`,
  `В S3: ${stats.s3_total} · локально: ${stats.local_total} · без изменений: ${stats.same} · пропущено: ${stats.skipped}`,
  `Новых: ${stats.missing} · изменённых: ${stats.changed} · к загрузке: ${stats.to_download}`,
  stats.dry_run ? '⚠️ РЕЖИМ ПРОВЕРКИ (dry_run = true) — ничего не скачано' : `✅ Скачано и записано: ${written}`,
];
const plan = Array.isArray(first.plan) ? first.plan : [];
if (plan.length) lines.push('', ...plan.slice(0, 80));
if (plan.length > 80) lines.push(`… ещё ${plan.length - 80}`);
return [{ json: { ok: true, written, stats, plan, message: lines.join('\n') } }];
